{"input_code": "from scipy.optimize import least_squares
def kepE(M,e):
    E=M.copy()
    for _ in range(50): E=E-(E-e*np.sin(E)-M)/(1-e*np.cos(E))
    return E
def kep_rv(th,t):
    P,K,e,w,M0=th
    M=M0+2*np.pi*(t-t_ref_days)/P
    E=kepE(np.mod(M,2*np.pi),e)
    nu=2*np.arctan2(np.sqrt(1+e)*np.sin(E/2),np.sqrt(1-e)*np.cos(E/2))
    return K*(np.cos(nu+w)+e*np.cos(w))
def model_fn(p,t,n):
    out=np.full_like(t,p[5*n])
    for i in range(n): out=out+kep_rv(p[5*i:5*i+5],t)
    return out
def resid_fn(p,n): return (rvs_ms-model_fn(p,times_days,n))/sigmas_ms
bestfit=None
for e0 in [0.02,0.1,0.2,0.35]:
  for w0 in np.linspace(0,2*np.pi,6,endpoint=False):
    for M0 in np.linspace(0,2*np.pi,6,endpoint=False):
      p0=[15.33,78,e0,w0,M0,0]
      try:
        r=least_squares(resid_fn,p0,args=(1,),bounds=([14,10,0,-10,-20,-100],[17,200,0.8,20,30,100]))
      except Exception: continue
      if bestfit is None or r.cost<bestfit.cost: bestfit=r
p1=bestfit.x; fit_res=rvs_ms-model_fn(p1,times_days,1)
print('params',p1,'RMS',np.sqrt(np.mean(fit_res**2)),'chi2r',2*bestfit.cost/(80-6))
fr2=np.linspace(1/40,1/0.6,20000); pw2=lombscargle(times_days,fit_res-fit_res.mean(),2*np.pi*fr2,normalize=True)
for i in np.argsort(pw2)[::-1][:5]: print('resid peak',1/fr2[i],pw2[i])"}

